module AtomicCompareA
on Start {
  let left be nothing
  let rightNothing be nothing
  let rightBoolean be true
  let rightInteger be 10
  let rightFloat be 0.5
  let rightPercentage be 50%
  let rightQuantity be 10m
  let rightText be '10'
  let rightNumericTag be pi
  let rightPlainTag be #custom
  let rightVector be :vector(1, 2, 3)
  let rightPoint be :point(1, 2, 3)
  let rightList be [1, 'x']
  let rightMap be [name: 'Ada', hp: 10]
  let rightDice be roll dice 2d6
  let rightRange be from 1 to 3
  let rightMessage be Ping(amount: 10)
  let rightHandler be Ping(amount)
  let rightSeries be :series.natural()
  emit Done(nothing: left < rightNothing, boolean: left < rightBoolean, integer: left < rightInteger, float: left < rightFloat, percentage: left < rightPercentage, quantity: left < rightQuantity, text: left < rightText, numericTag: left < rightNumericTag, plainTag: left < rightPlainTag, vector: left < rightVector, point: left < rightPoint, list: left < rightList, map: left < rightMap, dice: left < rightDice, range: left < rightRange, message: left < rightMessage, handler: left < rightHandler, series: left < rightSeries)
}

